#!/bin/bash
# Regenerates Anvil/Providers/PresetData.swift from Anvil/Providers/Presets/*.json.
# The Mac app loads the presets from its bundle; Linux and SwiftPM builds use this embedded copy.
# Run after editing any preset JSON, then commit both. AnvilTests/PresetDataTests fails if they drift (on macOS).
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
out="$root/Anvil/Providers/PresetData.swift"
{
cat <<'HDR'
// GENERATED by scripts/sync-presets.sh from Anvil/Providers/Presets/*.json. Do not edit by hand.

nonisolated enum PresetData {
    static let files: [String: String] = [
HDR
for f in "$root"/Anvil/Providers/Presets/*.json; do
    # Raw string: the value is the file's exact bytes. The closing delimiter sits at column 0 (required for raw
    # multi-line strings), and the newline before it is stripped, so one extra newline keeps the file's own final newline.
    printf '        "%s": #"""\n' "$(basename "$f")"
    cat "$f"
    printf '\n"""#,\n'
done
cat <<'FTR'
    ]
}
FTR
} > "$out"
echo "wrote $out"
